  const mgRulesUp = () => { const ov = document.getElementById('ov'); if (!ov || ov.hidden) return false; return [...ov.querySelectorAll('button')].some(b => /^\s*sẵn sàng/i.test(b.textContent || '') && b.getClientRects().length && b.offsetParent !== null) }; /* a mini-game RULES board is on screen (its «Sẵn sàng» starts the round) */
  const LAYER = '#modal,#ov,.modal,.ov,[role=dialog],.dlg,.kpdlg,#dawn,.kne,.kmov,.kscn,#kroul,.kroul,#kpop,.kpop,#title,.title,#kload,#klife'; /* .kscn = the kit story scene (jkitsel kitScene, fixed over the stage, its .kscn-veil covers the page; a tap anywhere on it moves the dialogue on — E-S1 b1 «Chạm để tiếp ▸» stuck: the robot saw only the covered page) */
  const W = innerWidth, H = innerHeight;
